#define PI 3.14159265358979323846

#define cleargreen vec3(0.353, 0.549, 0.518) // #5a8c84
#define green1 vec3(0, 0.353, 0.161) // #005a29
#define green2 vec3(0, 0.192, 0.094) // #00311e

vec2 rotate2D(vec2 _st, float _angle) {
    _st -= 0.5;
    _st = mat2(cos(_angle), -sin(_angle), sin(_angle), cos(_angle)) * _st;
    _st += 0.5;
    return _st;
}

vec2 tile(vec2 _st, float _zoom) {
    _st *= _zoom;
    return fract(_st);
}

float line(in vec2 _st, in float _width, in vec2 coord) {
    if(coord.x == 0.0) {
        return 1.0 - step(_width, abs(_st.y - coord.y));
    } else if(coord.y == 0.0) {
        return 1.0 - step(_width, abs(_st.x - coord.x));
    } else {
        return 0.0;
    }
}

float rectangle(in vec2 st, in vec2 origin, in vec2 dimensions) {
    vec2 bl = step(origin, st);
    float pct = bl.x * bl.y;
    vec2 tr = step(1.0 - origin - dimensions, 1.0 - st);
    pct *= tr.x * tr.y;
    return pct;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
   vec2 st = fragCoord.xy / iResolution.xy;
    vec3 color = vec3(0.0);

    // Divide the space in 4
    st = tile(st, 5.);

    // Draw a square
  //color = vec3(box(st, vec2(0.98), 0.01));
  //rectangles
    color += vec3(rectangle(st, vec2(0.0), vec2(0.3, 0.2))) * green2;
    color += vec3(rectangle(st, vec2(0.6, 0.0), vec2(0.3, 0.2))) * green2;
    color += vec3(rectangle(st, vec2(0.3, 0.0), vec2(0.3, 0.2))) * green2 * 0.5;
