    color += vec3(rectangle(st, vec2(0.0, 0.2), vec2(0.3, 0.4))) * green2 * 0.5;
    color += vec3(rectangle(st, vec2(0.6, 0.2), vec2(0.3, 0.4))) * green2 * 0.5;
    color += vec3(rectangle(st, vec2(0.0, 0.6), vec2(0.3, 0.4))) * green2;
    color += vec3(rectangle(st, vec2(0.3, 0.6), vec2(0.3, 0.4))) * green2 * 0.5;
