    color += vec3(line(st, 0.01, vec2(0.95, 0.))) * green1 * 0.5;
  //horizontal lines
    color += vec3(line(st, 0.01, vec2(0.0, 0.4))) * cleargreen * 0.5;
    color += vec3(line(st, 0.01, vec2(0.0, 0.47))) * cleargreen * 0.5;
